package io.github.jesterportfolio.hearth.quest;

import io.github.jesterportfolio.hearth.crafting.*;
import io.github.jesterportfolio.hearth.story.*;
import io.github.jesterportfolio.hearth.combat.DungeonPlay;
import io.github.jesterportfolio.hearth.gathering.GatheringContent;
import io.github.jesterportfolio.hearth.exploration.*;
import io.github.jesterportfolio.hearth.persistence.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class PreparationGuideTest {
    static QuestCatalog catalog(boolean locked){var q=QuestCatalogTest.quest("survey_marker","survey_guide");q.put("objective",Map.of("min-x",12,"max-x",14,"min-y",64,"max-y",67,"min-z",12,"max-z",14,"interaction","dungeon:trial","description","시험 던전 목표"));if(locked)q.put("requires-completed","path_marker");return QuestCatalog.parse(List.of(QuestCatalogTest.npc("survey_guide",3),QuestCatalogTest.npc("path_guide",10)),List.of(q,QuestCatalogTest.quest("path_marker","path_guide")));}
    static CraftContent crafting(){return CraftingQuestTest.recipes();}
    static Map<String,Object> entry(String id,String kind,String ref,String place){var m=new HashMap<String,Object>(Map.of("id",id,"title","공개 준비 "+id,"kind",kind,"reference",ref,"hint","현장에서 확인하세요"));if(place!=null)m.put("place",place);return m;}
    static Map<String,Object> root(){var c=entry("workbench","CRAFTING","bench","workshop");c.put("recipes",List.of("planks"));var d=entry("dungeon","DUNGEON","trial",null);d.put("quest","survey_marker");return new HashMap<>(Map.of("format",1,"public-prototype",true,"material-names",Map.of("OAK_LOG","참나무 원목"),"entries",new ArrayList<>(List.of(entry("gathering","GATHERING","material_site","materials"),c,d))));}
    static ExplorationContent exploration(){var places=new HashMap<String,ExplorationContent.Place>();for(String id:List.of("materials","workshop")){var area=id.equals("materials")?new QuestContent.Area(20,21,64,65,20,21):new QuestContent.Area(12,14,64,65,12,14);places.put(id,new ExplorationContent.Place(id,"marker_"+id,"공개 장소","region","시설",ExplorationContent.Visibility.PUBLIC,ExplorationContent.Discovery.ENTRY,area,new ExplorationContent.Location("NONE","위치 비공개"),null,false,null,null));}return new ExplorationContent(Map.of("region",new ExplorationContent.Region("region","공개 지역",true)),places,Map.of(),Map.of(),Map.of());}
    static GatheringContent gathering(){var area=new GatheringContent.Box(20,63,20,2,3,2);var blocks=new HashMap<GatheringContent.Cell,String>();for(var cell:area.cells())blocks.put(cell,"AIR");return new GatheringContent("material_site",area,new GatheringContent.Position(5,64,5,0,0),new GatheringContent.Position(20.5,64,20.5,0,0),60000,1000,"one",Map.of("one",new GatheringContent.Template("one",blocks)));}
    static PreparationGuide parse(Map<?,?> root){return PreparationGuide.parse(root,catalog(false),crafting(),exploration(),gathering(),new DungeonPlay.Definition("trial","survey_marker","survey_guide",new QuestContent.Area(12,14,64,67,12,14)));}
    static QuestJournal.View view(QuestStore.Phase phase,Set<String> blocked,boolean places){var v=PlaythroughTest.view(PlaythroughTest.rows(phase),SharedStoryTest.empty(),blocked);var x=v.exploration();var shown=places?List.of(new ExplorationView.Place("materials","공개 채집장","공개 지역","시설","공개 탐색 구역","미발견",false,false,false),new ExplorationView.Place("workshop","공개 제작대","공개 지역","시설","위치 비공개","발견",true,true,false)):List.<ExplorationView.Place>of();return new QuestJournal.View(v.states(),v.journal(),new ExplorationView(true,x.regions(),shown,x.facts(),x.events(),x.members(),x.story(),x.conditions(),x.nextGoal(),blocked,x.branches()));}
    static PreparationGuide.Facts facts(int logs,boolean entry,boolean dirty,boolean saving){return new PreparationGuide.Facts(Map.of("planks",CraftingMaterials.view(crafting().recipes().get("planks"),Map.of("OAK_LOG",logs))),List.of("자원 준비 대기"),List.of("본인 도전 대기"),entry,dirty,saving);}
    @Test void ownMaterialsAndStatusesAreReadOnlyAndImmutable(){var p=parse(root());var v=view(QuestStore.Phase.ACTIVE,Set.of(),true);var rows=Map.copyOf(v.states());var page=p.build(catalog(false),crafting(),v,facts(2,true,true,false));assertEquals(3,page.cards().size());assertTrue(page.card("workbench").lines().toString().contains("참나무 원목 · 필요 1 / 보유 2 / 부족 0"));assertTrue(page.card("dungeon").lines().toString().contains("입구 범위 안"));assertTrue(page.card("dungeon").lines().toString().contains("새 필수 입장 조건이 아닙니다"));assertTrue(page.card("dungeon").lines().toString().contains("저장 대기"));assertEquals(rows,v.states());assertThrows(UnsupportedOperationException.class,()->page.cards().clear());assertThrows(UnsupportedOperationException.class,()->page.card("dungeon").lines().clear());}
    @Test void unknownQuestAndFilteredPlacesNeverRevealDefinitions(){var p=parse(root());var page=p.build(catalog(false),crafting(),view(QuestStore.Phase.NOT_ACCEPTED,Set.of(),true),facts(0,false,false,false));assertNull(page.card("dungeon").quest());for(String privateText:List.of("survey_marker","공개 시험 안내원","시험 던전 목표","본인 도전 대기","12.0","20.5"))assertFalse(page.toString().contains(privateText));var hidden=p.build(catalog(false),crafting(),view(QuestStore.Phase.NOT_ACCEPTED,Set.of("survey_marker"),false),facts(0,false,false,false));assertTrue(hidden.cards().isEmpty());var locked=p.build(catalog(true),crafting(),view(QuestStore.Phase.NOT_ACCEPTED,Set.of(),true),facts(0,false,false,false));assertEquals(2,locked.cards().size());}
    @Test void reportingCompletionAndExistingAcceptedPrerequisiteArePreserved(){var p=parse(root());var report=p.build(catalog(true),crafting(),view(QuestStore.Phase.REPORT_READY,Set.of(),true),facts(0,false,false,false));assertTrue(report.card("dungeon").lines().toString().contains("보고를 마치세요"));var done=p.build(catalog(true),crafting(),view(QuestStore.Phase.COMPLETED,Set.of(),true),facts(0,false,false,false));assertTrue(done.card("dungeon").lines().toString().contains("새 도전을 자동 생성하지 않습니다"));}
    @Test void materialLocationSavingPhaseAndVisibilityChangesRejectOldSelection(){var p=parse(root());var v=view(QuestStore.Phase.ACTIVE,Set.of(),true);var before=p.build(catalog(false),crafting(),v,facts(0,false,false,false));PreparationGuide.require(before,before,"workbench");for(var changed:List.of(facts(1,false,false,false),facts(0,true,false,false),facts(0,false,true,false),facts(0,false,false,true)))assertThrows(IllegalStateException.class,()->PreparationGuide.require(p.build(catalog(false),crafting(),v,changed),before,"workbench"));assertThrows(IllegalStateException.class,()->PreparationGuide.require(p.build(catalog(false),crafting(),view(QuestStore.Phase.REPORT_READY,Set.of(),true),facts(0,false,false,false)),before,"dungeon"));assertThrows(RuntimeException.class,()->PreparationGuide.require(p.build(catalog(false),crafting(),view(QuestStore.Phase.ACTIVE,Set.of("survey_marker"),true),facts(0,false,false,false)),before,"dungeon"));}
    @Test void missingOrWrongMaterialsAreFailuresNotEmptySuccess(){var p=parse(root());var v=view(QuestStore.Phase.ACTIVE,Set.of(),true);assertThrows(IllegalStateException.class,()->p.build(catalog(false),crafting(),v,new PreparationGuide.Facts(Map.of(),List.of(),List.of(),false,false,false)));assertThrows(IllegalStateException.class,()->p.build(catalog(false),crafting(),v,new PreparationGuide.Facts(Map.of("planks",List.of(new CraftingMaterials.Need("OAK_LOG",2,2))),List.of(),List.of(),false,false,false)));}
    @SuppressWarnings("unchecked") @Test void badReferencesAndDuplicateDefinitionsFailBeforeActivation(){for(String field:List.of("reference","place","recipes","quest")){var r=root();var entries=(List<Map<String,Object>>)r.get("entries");var row=entries.get(field.equals("quest")?2:1);row.put(field,field.equals("recipes")?List.of("unknown"):"unknown");assertThrows(IllegalArgumentException.class,()->parse(r));}var duplicate=root();var entries=(List<Map<String,Object>>)duplicate.get("entries");entries.add(entries.getFirst());assertThrows(IllegalArgumentException.class,()->parse(duplicate));var labels=root();labels.put("material-names",Map.of());assertThrows(IllegalArgumentException.class,()->parse(labels));}
}
